text(ALL_TOOLS.filter(x=>/composio/i.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,160)})));
text(await tools.exec_command({cmd:"rg -n 'Product Hunt|Tron|archive|contem' /Users/serro/.codex/memories/MEMORY.md","max_output_tokens":5000}));

const results=await Promise.allSettled([
tools.exec_command({cmd:"composio connections list","max_output_tokens":5000}),
tools.exec_command({cmd:"composio search 'Search Notion pages by title and list page block contents' --toolkits notion","max_output_tokens":6000}),
tools.exec_command({cmd:"git status --short; rg --files -g 'AGENTS.md' -g 'README.md' -g 'package.json' -g 'SPEC.md' -g '!node_modules' -g '!package-lock.json' | head -180","max_output_tokens":6000}),
tools.exec_command({cmd:"sed -n '816,842p' /Users/serro/.codex/memories/MEMORY.md","max_output_tokens":3000})
]);results.forEach((r,i)=>text({i,...r}));

