const results=await Promise.allSettled([
tools.exec_command({cmd:"composio execute NOTION_SEARCH_NOTION_PAGE --get-schema","max_output_tokens":4000}),
tools.exec_command({cmd:"composio execute NOTION_GET_PAGE_MARKDOWN --get-schema","max_output_tokens":4000}),
tools.exec_command({cmd:"composio execute NOTION_FETCH_BLOCK_CONTENTS --get-schema","max_output_tokens":4000}),
tools.exec_command({cmd:"rg --files -g AGENTS.md -g '!node_modules' -g '!**/examples/**'; sed -n '1,180p' README.md; cat package.json","max_output_tokens":10000})
]);results.forEach((r,i)=>text({i,...r}));

