def get(p):
 title=''.join(t.get('plain_text','') for v in p['properties'].values() for t in v.get('title',[])); day=re.search(r'2026-\d\d-\d\d',title)[0]
 target=out/(day+'.markdown.json')
 if target.exists(): d=json.loads(target.read_text())
