 return {'day':day,'chars':len(md),'truncated':d['data'].get('truncated'),'unknown':d['data'].get('unknown_block_ids'),'files':files}
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
 for r in pool.map(get,pages): print(json.dumps(r),flush=True)
